const TIMEZONE = "America/Sao_Paulo";

function todayInTZ() {
  const now = new Date();
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: TIMEZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const map = Object.fromEntries(parts.map((p) => [p.type, p.value]));
  return new Date(`${map.year}-${map.month}-${map.day}T00:00:00`);
}

function lastDayOfMonth(year, monthIndex) {
  return new Date(year, monthIndex + 1, 0).getDate();
}

function nextMonthlyOccurrence(day, today) {
  const clampedDay = (year, monthIndex) => Math.min(day, lastDayOfMonth(year, monthIndex));
  const thisMonth = new Date(
    today.getFullYear(),
    today.getMonth(),
    clampedDay(today.getFullYear(), today.getMonth())
  );
  if (thisMonth >= today) return thisMonth;
  const nextMonthIndex = today.getMonth() + 1;
  const year = today.getFullYear() + Math.floor(nextMonthIndex / 12);
  const monthIndex = nextMonthIndex % 12;
  return new Date(year, monthIndex, clampedDay(year, monthIndex));
}

function formatDateBR(date) {
  return date.toLocaleDateString("pt-BR", { day: "2-digit", month: "2-digit", year: "numeric" });
}

const today = todayInTZ();
const matches = [];

for (const item of items) {
  const sub = item.json;
  if (sub.recurrence_type !== "monthly_day" && sub.recurrence_type !== "fixed_date") continue;

  let dueDate;
  if (sub.recurrence_type === "fixed_date") {
    if (!sub.recurrence_date) continue;
    dueDate = new Date(`${sub.recurrence_date}T00:00:00`);
  } else {
    if (!sub.recurrence_day) continue;
    dueDate = nextMonthlyOccurrence(Number(sub.recurrence_day), today);
  }

  // Aviso normal: 1 dia antes do vencimento.
  // Se esse dia cair num domingo, avisa na sexta-feira anterior.
  const notifyDate = new Date(dueDate);
  notifyDate.setDate(notifyDate.getDate() - 1);
  if (notifyDate.getDay() === 0) {
    notifyDate.setDate(notifyDate.getDate() - 2);
  }

  if (notifyDate.getTime() === today.getTime()) {
    matches.push({
      platform: sub.platform,
      subject: sub.subject,
      amount: sub.amount,
      currency: sub.currency || "BRL",
      dueDate: formatDateBR(dueDate),
    });
  }
}

const lines = matches.map((m) => {
  const valor = m.amount != null ? ` \u2014 ${m.currency} ${Number(m.amount).toFixed(2)}` : "";
  const assunto = m.subject ? ` (${m.subject})` : "";
  return `- ${m.platform}${assunto}: vence em ${m.dueDate}${valor}`;
});

const subject = `Aviso de vencimento - ${matches.length} assinatura${matches.length === 1 ? "" : "s"}`;
const bodyText = `Assinaturas com vencimento proximo:\n\n${lines.join("\n")}\n\nEnviado automaticamente pelo n8n.`;

return [{ json: { matches, count: matches.length, subject, bodyText } }];
